import { queryOptions, useQuery } from '@tanstack/react-query'

export interface CatalogItem {
  id: string
  name: string
  price: number
}

export interface CatalogParams {
  category?: string
  page?: number
}

const CATALOG_ENDPOINT = '/api/catalog'

async function fetchCatalog(params: CatalogParams): Promise<CatalogItem[]> {
  const search = new URLSearchParams(
    Object.entries(params).filter(([, value]) => value !== undefined),
  )
  const response = await fetch(`${CATALOG_ENDPOINT}?${search}`)
  if (!response.ok) {
    throw new Error(`Failed to load catalog: HTTP ${response.status}`)
  }
  return (await response.json()) as CatalogItem[]
}

export const catalogQueryOptions = (params: CatalogParams = {}) =>
  queryOptions({
    queryKey: ['catalog', params],
    queryFn: () => fetchCatalog(params),
  })

export function useCatalogQuery(params: CatalogParams = {}) {
  return useQuery(catalogQueryOptions(params))
}

